<?php
namespace App\Controllers\Api;
class LaporanController extends BaseApiController
{
 public function index(){ $kelas=(int)$this->request->getGet('kelas_id');if(!$kelas)return $this->respond(['ok'=>false,'message'=>'Kelas wajib dipilih.'],422);return $this->respond(['data'=>$this->build($kelas)]);}
 public function csv(){ $kelas=(int)$this->request->getGet('kelas_id');if(!$kelas)return $this->respond(['ok'=>false,'message'=>'Kelas wajib dipilih.'],422);$report=$this->build($kelas);$stream=fopen('php://temp','r+');fputcsv($stream,['LAPORAN WALI KELAS']);fputcsv($stream,['Kelas',$report['kelas']['nama_kelas']??'']);fputcsv($stream,['Tahun Ajaran',($report['kelas']['nama_tahun_ajaran']??'').' '.($report['kelas']['semester']??'')]);fputcsv($stream,[]);fputcsv($stream,['NIS','Nama Siswa','Rata-rata Nilai','Sakit','Izin','Alpha','Total Ketidakhadiran']);foreach($report['siswa'] as $row)fputcsv($stream,array_map([$this,'safeCsv'],[$row['nis'],$row['nama_lengkap'],$row['rata_rata']??'',(int)$row['sakit'],(int)$row['izin'],(int)$row['alpha'],(int)$row['jumlah_absen']]));rewind($stream);$csv=stream_get_contents($stream);fclose($stream);return $this->response->setHeader('Content-Type','text/csv; charset=UTF-8')->setHeader('Content-Disposition','attachment; filename="laporan-wali-kelas-'.date('Ymd').'.csv"')->setBody("\xEF\xBB\xBF".$csv);}
 private function build(int $kelas):array{$db=db_connect();$class=$db->table('kelas')->select('kelas.*,tahun_ajaran.nama_tahun_ajaran,tahun_ajaran.semester,pengguna.nama_lengkap AS wali_kelas')->join('tahun_ajaran','tahun_ajaran.id=kelas.tahun_ajaran_id')->join('pengguna','pengguna.id=kelas.wali_kelas_id','left')->where('kelas.id',$kelas)->get()->getRowArray();if(!$class)return ['kelas'=>null,'siswa'=>[],'mata_pelajaran'=>[]];$students=$db->table('siswa')->select("siswa.id,siswa.nis,siswa.nama_lengkap,(SELECT ROUND(AVG(ns.nilai),2) FROM nilai_siswa ns WHERE ns.siswa_id=siswa.id) rata_rata,(SELECT COUNT(*) FROM absensi a WHERE a.siswa_id=siswa.id AND a.status='Sakit') sakit,(SELECT COUNT(*) FROM absensi a WHERE a.siswa_id=siswa.id AND a.status='Izin') izin,(SELECT COUNT(*) FROM absensi a WHERE a.siswa_id=siswa.id AND a.status='Alpha') alpha,(SELECT COUNT(*) FROM absensi a WHERE a.siswa_id=siswa.id AND a.status IN ('Sakit','Izin','Alpha')) jumlah_absen",false)->where(['siswa.kelas_id'=>$kelas,'siswa.aktif'=>1])->orderBy('siswa.nama_lengkap')->get()->getResultArray();$subjects=$db->table('mata_pelajaran')->select('mata_pelajaran.id,mata_pelajaran.nama_mata_pelajaran,ROUND(AVG(nilai_siswa.nilai),2) rata_rata,MIN(nilai_siswa.nilai) nilai_minimum,MAX(nilai_siswa.nilai) nilai_maksimum,COUNT(DISTINCT komponen_nilai.id) jumlah_komponen',false)->join('komponen_nilai','komponen_nilai.mata_pelajaran_id=mata_pelajaran.id AND komponen_nilai.kelas_id='.$kelas,'left')->join('nilai_siswa','nilai_siswa.komponen_nilai_id=komponen_nilai.id','left')->groupBy('mata_pelajaran.id')->orderBy('mata_pelajaran.nama_mata_pelajaran')->get()->getResultArray();return ['kelas'=>$class,'siswa'=>$students,'mata_pelajaran'=>$subjects,'dibuat_pada'=>date('Y-m-d H:i:s')];}
 public function safeCsv($value):string{$value=(string)$value;return preg_match('/^[=+\-@]/',$value)?"'".$value:$value;}
}